'use client';

// A suggestion's card (docs/specs/007-editor/suggestions.md "Reviewing"): with the caret inside a suggestion, or the
// pointer over it, a card under its first line says who made it and when, Generated by AI for an assistant's, and
// what it does; an Editor's has Accept and Reject, and Accept All for an assistant's change of more than one. Listens
// on the writing's own element, as the link card does, so the editor's keyboard handling is untouched.
import { useEffect, useRef, useState, type RefObject } from 'react';
import type { EditorView } from 'prosemirror-view';
import { lucideCheck, lucideSparkles, lucideX } from '@liveworkspace/icons/lucide';
import { lucideGlyph, Portal, SOLID_BRAND_DARK_CONTROL } from '@livedocuments/ui';
import {
  changeSize,
  resolveSuggestionsTr,
  selectFirstSuggestion,
  suggestionAt,
  suggestionById,
  type SuggestionAtPos,
} from '@/lib/article/article-suggest-resolve';
import { formatOf } from '@/lib/article/article-suggest';
import { describeSuggestion, suggestionAgo } from '@/lib/article/article-suggest-describe';
import {
  onSuggestionReview,
  sayToReviewer,
  takeSuggestionReview,
  type ReviewRequest,
} from '@/lib/article/article-suggest-store';
import { track } from '@/lib/telemetry';

// How long the card stays once the pointer leaves the suggestion, so it can cross to the card (ms).
const CARD_GRACE_MS = 250;

const Check = lucideGlyph(lucideCheck, 14);
const Cross = lucideGlyph(lucideX, 14);
const Spark = lucideGlyph(lucideSparkles, 12);

type Open = { id: string; via: 'hover' | 'caret' };

/** "2 suggestions wait in paragraphs others are writing in". */
export const waitingCopy = (n: number): string =>
  `${n} suggestion${n === 1 ? '' : 's'} ${n === 1 ? 'waits' : 'wait'} in paragraphs others are writing in`;

/** Decides the suggestions `pick` names in `view`, as one edit, and says how many wait in held paragraphs. */
export function decideIn(
  view: EditorView,
  pick: Parameters<typeof resolveSuggestionsTr>[1],
): number {
  const { tr, decided, waiting } = resolveSuggestionsTr(view.state, pick);
  if (decided > 0) view.dispatch(tr);
  if (waiting > 0) sayToReviewer(waitingCopy(waiting));
  return decided;
}

function describe(view: EditorView, s: SuggestionAtPos): string {
  if (s.isBreak)
    return describeSuggestion({ k: s.attrs.k === 'del' ? 'del' : 'ins', isBreak: true });
  if (s.attrs.k === 'fmt') {
    const node = view.state.doc.nodeAt(s.from);
    return describeSuggestion({
      k: 'fmt',
      was: s.attrs.was ?? {},
      now: formatOf(node?.marks ?? []),
      isBreak: false,
    });
  }
  return describeSuggestion({ k: s.attrs.k, text: s.text, isBreak: false });
}

export function useSuggestionCard(
  viewRef: RefObject<EditorView | null>,
  flow: string,
  canDecide: boolean,
): React.ReactNode {
  const [open, setOpen] = useState<Open | null>(null);
  // Re-read the suggestion when the writing changes under an open card (a decision elsewhere, a peer's typing).
  const [, setTick] = useState(0);
  const leave = useRef<number | null>(null);
  const card = useRef<HTMLDivElement>(null);
  const stay = () => {
    if (leave.current !== null) window.clearTimeout(leave.current);
    leave.current = null;
  };
  const go = () => {
    stay();
    leave.current = window.setTimeout(
      () => setOpen((o) => (o?.via === 'hover' ? null : o)),
      CARD_GRACE_MS,
    );
  };

  useEffect(() => {
    const view = viewRef.current;
    if (!view) return;
    const dom = view.dom;
    const idAt = (target: EventTarget | null) =>
      ((target as Element | null)?.closest?.('[data-sg-id]') as HTMLElement | null)?.dataset.sgId ||
      null;
    const over = (e: MouseEvent) => {
      const id = idAt(e.target);
      if (!id) return;
      stay();
      setOpen((o) => (o?.id === id ? o : { id, via: 'hover' }));
    };
    const out = (e: MouseEvent) => {
      if (idAt(e.target)) go();
    };
    // The caret's suggestion, once a key or a press has moved it.
    const caret = () => {
      const { selection } = view.state;
      const s = selection.empty ? suggestionAt(view.state, selection.head) : null;
      setOpen((o) => (s ? { id: s.attrs.id, via: 'caret' } : o?.via === 'caret' ? null : o));
      setTick((t) => t + 1);
    };
    const key = (e: KeyboardEvent) => {
      if (e.key === 'Escape') return;
      caret();
    };
    // Escape closes the card first; the next one leaves the writing as before.
    const escape = (e: KeyboardEvent) => {
      if (e.key !== 'Escape') return;
      setOpen((o) => {
        if (!o) return o;
        e.stopPropagation();
        e.preventDefault();
        return null;
      });
    };
    const review = (r: ReviewRequest) => {
      if (r.flow !== flow) return;
      takeSuggestionReview(flow);
      const tr = selectFirstSuggestion(view.state, r.g);
      if (!tr) return;
      view.dispatch(tr);
      view.focus();
      caret();
    };
    dom.addEventListener('mouseover', over);
    dom.addEventListener('mouseout', out);
    dom.addEventListener('keyup', key);
    dom.addEventListener('mouseup', caret);
    dom.addEventListener('keydown', escape, true);
    const offReview = onSuggestionReview(review);
    // A request made before this article was on screen (its tab opening from the toast).
    const pending = takeSuggestionReview(flow);
    if (pending) review(pending);
    return () => {
      dom.removeEventListener('mouseover', over);
      dom.removeEventListener('mouseout', out);
      dom.removeEventListener('keyup', key);
      dom.removeEventListener('mouseup', caret);
      dom.removeEventListener('keydown', escape, true);
      offReview();
      stay();
    };
    // oxlint-disable-next-line react/exhaustive-deps -- the view is made once, before this runs
  }, [flow]);

  const view = viewRef.current;
  if (!open || !view) return null;
  const s = suggestionById(view.state, open.id);
  if (!s) return null;
  let at: { left: number; bottom: number };
  try {
    at = view.coordsAtPos(Math.min(s.isBreak ? s.from + 1 : s.from, view.state.doc.content.size));
  } catch {
    return null;
  }
  const { attrs } = s;
  const many = attrs.ai && attrs.g ? changeSize(view.state, attrs.g) : 0;
  const close = () => {
    setOpen(null);
    view.focus();
  };
  const decide = (d: 'accept' | 'reject') => {
    if (decideIn(view, (x) => (x.id === attrs.id ? d : null)) > 0)
      track('Element', 'Changed', d === 'accept' ? 'SuggestionAccepted' : 'SuggestionRejected');
    close();
  };
  const acceptChange = () => {
    const g = attrs.g;
    if (g && decideIn(view, (x) => (x.g === g ? 'accept' : null)) > 0)
      track('Element', 'Changed', 'SuggestionChangeAccepted');
    close();
  };
  const button =
    'inline-flex h-7 items-center gap-1 rounded-md px-2 text-xs font-medium transition focus-visible:outline-2 focus-visible:outline-brand-600';
  return (
    <Portal>
      <div
        ref={card}
        role="dialog"
        aria-label={`Suggestion by ${attrs.n}`}
        data-article-keep-active=""
        data-suggestion-card=""
        className="fixed z-[var(--z-overlay)] flex w-max min-w-[13rem] max-w-[20rem] animate-fade-in flex-col gap-1.5 rounded-lg border border-slate-200 bg-white p-2.5 shadow-lg shadow-slate-900/10 dark:border-slate-700 dark:bg-slate-900"
        style={{ left: at.left, top: at.bottom + 6 }}
        onPointerEnter={stay}
        onPointerLeave={() => {
          if (open.via === 'hover') go();
        }}
        onMouseDown={(e) => e.preventDefault()}
        onKeyDown={(e) => {
          if (e.key !== 'Escape') return;
          e.stopPropagation();
          close();
        }}
      >
        <div className="flex min-w-0 items-center gap-1.5 text-xs">
          <span
            aria-hidden="true"
            className="size-2.5 shrink-0 rounded-full ring-2 ring-white dark:ring-slate-900"
            style={{ background: attrs.c ?? '#6366f1' }}
          />
          <span className="min-w-0 truncate font-semibold text-slate-800 dark:text-slate-100">
            {attrs.n}
          </span>
          <span className="shrink-0 text-slate-500 dark:text-slate-400">
            {suggestionAgo(attrs.at, Date.now())}
          </span>
        </div>
        {attrs.ai ? (
          <span className="inline-flex w-fit items-center gap-1 rounded-full bg-violet-50 px-1.5 py-0.5 text-[11px] font-medium text-violet-700 dark:bg-violet-500/15 dark:text-violet-300">
            <Spark />
            Generated by AI
          </span>
        ) : null}
        <p className="text-sm leading-snug text-slate-700 [overflow-wrap:anywhere] dark:text-slate-200">
          {describe(view, s)}
        </p>
        {canDecide ? (
          <div className="flex items-center gap-1 pt-0.5">
            <button
              type="button"
              aria-label="Accept"
              className={`${button} bg-brand-700 text-white hover:bg-brand-800 ${SOLID_BRAND_DARK_CONTROL}`}
              onClick={() => decide('accept')}
            >
              <Check />
              Accept
            </button>
            <button
              type="button"
              aria-label="Reject"
              className={`${button} text-slate-600 hover:bg-slate-100 hover:text-slate-900 dark:text-slate-300 dark:hover:bg-slate-800 dark:hover:text-white`}
              onClick={() => decide('reject')}
            >
              <Cross />
              Reject
            </button>
            {many > 1 ? (
              <button
                type="button"
                aria-label={`Accept all ${many} suggestions from this change`}
                className={`${button} ml-auto text-brand-700 hover:bg-brand-50 dark:text-brand-300 dark:hover:bg-brand-500/15`}
                onClick={acceptChange}
              >
                Accept All {many}
              </button>
            ) : null}
          </div>
        ) : null}
      </div>
    </Portal>
  );
}
